import{_ as o,E as n,o as i,a as d,d as e,H as l}from"./chunks/framework.IehvnstE.js";const b=JSON.parse('{"title":"Установка","description":"Подробная инструкция по установке Stuzhik на Windows и Linux. Системные требования, пакеты AppImage, .deb и .rpm, обновление и удаление.","frontmatter":{"description":"Подробная инструкция по установке Stuzhik на Windows и Linux. Системные требования, пакеты AppImage, .deb и .rpm, обновление и удаление.","head":[["meta",{"name":"keywords","content":"stuzhik скачать, установить stuzhik, стужик, minecraft launcher download, системные требования"}]]},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),r={name:"guide/installation.md"};function s(u,t,p,h,c,g){const a=n("DownloadButton");return i(),d("div",null,[t[0]||(t[0]=e('<h1 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h1><p>Установщик для Windows, пакеты для Linux: что нужно компьютеру, как обновлять и как удалить.</p><h2 id="системные-требования" tabindex="-1">Системные требования <a class="header-anchor" href="#системные-требования" aria-label="Permalink to &quot;Системные требования&quot;">​</a></h2><p>Система: <strong>Windows 10 и новее</strong> или <strong>Linux x86_64 с glibc 2.38+</strong> (Debian 13, Ubuntu 24.04, Fedora 39 и новее).</p><table tabindex="0"><thead><tr><th></th><th>Минимум</th><th>Лучше</th></tr></thead><tbody><tr><td>Память</td><td>4 ГБ</td><td>16 ГБ</td></tr><tr><td>Диск</td><td>2 ГБ и место под сборки</td><td>SSD, 20 ГБ свободно</td></tr><tr><td>Видеокарта</td><td>OpenGL 3.3</td><td>OpenGL 3.3</td></tr></tbody></table><h2 id="скачать" tabindex="-1">Скачать <a class="header-anchor" href="#скачать" aria-label="Permalink to &quot;Скачать&quot;">​</a></h2>',6)),l(a),t[1]||(t[1]=e('<ol><li>Скачайте установщик кнопкой выше</li><li>Запустите его и пройдите шаги установщика</li></ol><p>Для Linux есть AppImage, .deb и .rpm: <a href="/download.html#linux">Скачать</a>, как их ставить и обновлять, описано <a href="#linux">ниже</a>. Для серверов на Linux есть <a href="/guide/cli.html">консольная версия</a>.</p><h2 id="обновление" tabindex="-1">Обновление <a class="header-anchor" href="#обновление" aria-label="Permalink to &quot;Обновление&quot;">​</a></h2><p>Stuzhik <strong>сам проверяет и ставит обновления</strong> при запуске. Настраивается в «Настройки → Обновления»:</p><ul><li>«Проверять обновления при запуске»: выключите, если автообновление не нужно</li><li>«Канал обновлений»: «Стабильный» или «Бета»</li></ul><p>Проверить вручную: «Проверить сейчас» там же, рядом с установленной версией. Можно и просто скачать новый установщик и запустить поверх старого: <strong>сборки, миры и настройки останутся</strong>.</p><h2 id="деинсталляция" tabindex="-1">Удаление <a class="header-anchor" href="#деинсталляция" aria-label="Permalink to &quot;Удаление {#деинсталляция}&quot;">​</a></h2><p>Как обычную программу: Параметры Windows → Приложения → Stuzhik → Удалить.</p><ul><li><strong>Уходит всегда</strong> служебное: кэш, логи, отчёты об ошибках, данные встроенного браузера, сохранённые входы в аккаунты (они лежат в диспетчере учётных данных Windows) и правило брандмауэра для Stuzhik Connect. Чтобы снять правило, Windows один раз попросит подтверждение администратора, и только если правило было создано</li><li><strong>Только с галочкой</strong> «Удалить также сборки и миры (все данные лаунчера)»: сборки, миры, настройки, Java и файлы игры. Без галочки они остаются, и после повторной установки всё на месте</li></ul><p>Обновление лаунчера ничего из этого не трогает.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux {#linux}&quot;">​</a></h2><p>Пакеты и для каких систем они: <a href="/download.html#linux">Скачать → Linux</a>. <strong>Нужны x86_64 и glibc 2.38 или новее</strong> (<code>ldd --version</code>).</p><ul><li><strong>Установка.</strong> AppImage: <code>chmod +x Stuzhik_*.AppImage</code> и запустить файл. .deb: <code>sudo apt install ./Stuzhik_*_amd64.deb</code>. .rpm: <code>sudo dnf install ./Stuzhik-*.x86_64.rpm</code> (openSUSE: <code>sudo zypper install</code>)</li><li><strong>Обновление.</strong> Как на Windows: лаунчер находит новую версию сам. AppImage он заменяет на месте, .deb и .rpm ставит система и один раз спрашивает пароль</li><li><strong>Удаление.</strong> <code>sudo apt remove stuzhik</code> или <code>sudo dnf remove stuzhik</code>, AppImage просто удаляется. Сборки, миры и настройки остаются в <code>~/.local/share/ru.sibxodev.stuzhik</code>: удалите эту папку, если они больше не нужны</li><li><strong>AppImage не запускается на Ubuntu 24.04.</strong> Нужна библиотека FUSE 2: <code>sudo apt install libfuse2t64</code>. Или запустите <code>./Stuzhik_*.AppImage --appimage-extract-and-run</code></li><li><strong>Ошибка «GLIBC_2.38 not found».</strong> Система старше нужной (Debian 12, Ubuntu 22.04), приложение на ней не запустится. Серверы на ней работают через <a href="/guide/cli.html">консольную версию</a></li></ul><h2 id="если-лаунчер-не-запускается" tabindex="-1">Если лаунчер не запускается <a class="header-anchor" href="#если-лаунчер-не-запускается" aria-label="Permalink to &quot;Если лаунчер не запускается&quot;">​</a></h2><p>На Windows поставьте <a href="https://developer.microsoft.com/en-us/microsoft-edge/webview2/" target="_blank" rel="noreferrer">WebView2 Runtime</a>: окно лаунчера рисует он.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">winget</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> Microsoft.EdgeWebView2Runtime</span></span></code></pre></div>',16))])}const _=o(r,[["render",s]]);export{b as __pageData,_ as default};
